#!/usr/bin/env node
"use strict";

/**
 * tools/mobile/verify-bundle-size.js
 *
 * Checks the total size of apps/mobile/assets/audio (the bundled hybrid-delivery
 * mp3s generated by tools/tts/gen_tts_batch.py, see tools/tts/README.md) so that
 * Naoya can sanity-check app bundle size before an EAS build (Issue #225).
 *
 * Optional / manual only — not wired into CI. Run manually:
 *
 *   node tools/mobile/verify-bundle-size.js
 *   node tools/mobile/verify-bundle-size.js --limit-mb 50
 *
 * Exit code is non-zero if the total exceeds --limit-mb, so it can also be used
 * as a manual gate (e.g. before eas build --profile production).
 */

const fs = require("fs");
const path = require("path");

const REPO_ROOT = path.resolve(__dirname, "..", "..");
const AUDIO_DIR = path.join(REPO_ROOT, "apps", "mobile", "assets", "audio");

const DEFAULT_LIMIT_MB = 100;

function parseArgs(argv) {
  const args = { limitMb: DEFAULT_LIMIT_MB };
  for (let i = 0; i < argv.length; i++) {
    if (argv[i] === "--limit-mb") {
      const value = Number(argv[i + 1]);
      if (!Number.isNaN(value) && value > 0) {
        args.limitMb = value;
      }
      i++;
    }
  }
  return args;
}

function walk(dir) {
  const files = [];
  if (!fs.existsSync(dir)) return files;
  for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
    const fullPath = path.join(dir, entry.name);
    if (entry.isDirectory()) {
      files.push(...walk(fullPath));
    } else if (entry.isFile()) {
      files.push(fullPath);
    }
  }
  return files;
}

function formatBytes(bytes) {
  return (bytes / (1024 * 1024)).toFixed(2) + " MB";
}

function main() {
  const { limitMb } = parseArgs(process.argv.slice(2));

  if (!fs.existsSync(AUDIO_DIR)) {
    console.log(
      `[verify-bundle-size] ${path.relative(REPO_ROOT, AUDIO_DIR)} does not exist yet ` +
        "(bundled audio has not been generated — see tools/tts/README.md's " +
        "gen_tts_batch.py section). Nothing to check."
    );
    process.exit(0);
  }

  const files = walk(AUDIO_DIR);
  const totalBytes = files.reduce((sum, file) => sum + fs.statSync(file).size, 0);

  console.log(`[verify-bundle-size] ${path.relative(REPO_ROOT, AUDIO_DIR)}`);
  console.log(`  files: ${files.length}`);
  console.log(`  total size: ${formatBytes(totalBytes)}`);
  console.log(`  limit: ${limitMb} MB`);

  const totalMb = totalBytes / (1024 * 1024);
  if (totalMb > limitMb) {
    console.error(
      `[verify-bundle-size] FAIL: bundled audio (${formatBytes(totalBytes)}) exceeds ` +
        `the ${limitMb} MB limit. Consider lowering --top-n in tools/tts/gen_tts_batch.py ` +
        "or raising --limit-mb if this is expected."
    );
    process.exit(1);
  }

  console.log("[verify-bundle-size] OK: bundled audio size is within the limit.");
  process.exit(0);
}

main();
